	};

    scwin.typeGetter = function ( info ) {             
        var rowIndex = info.rowIndex;
        var colIndex = info.colIndex;
        var returnInfo;

        if (dataList1.getCellData(rowIndex, "custom").length > 2) {
            returnInfo = {
                id : "dynamic_select_" + rowIndex + "_" + colIndex,
                inputType : "calendar",
                options : {
                    viewType: "icon"
                }
            };
        } else {
            returnInfo = {
                id : "dynamic_text_" + rowIndex + "_" + colIndex,
                inputType : "text",
                options : {
                }
            };
        }

        if(returnInfo) {
            //console.log( "[typeGetter] (" + rowIndex + ", " + colIndex + ") : " +returnInfo.inputType);
        }

        return returnInfo;
    };
    scwin.trigger1_onclick = function(e) {
        gridView1.setCellReadOnly(0,2,true)
	};
    scwin.trigger2_onclick = function(e) {
        text.getUserData("userData1")
	};
    scwin.gridView1_checkboxLabelFormatter = function(row, col, label){
        return label + ":[" + row + "," + col + "]";
    }
    scwin.customFormatter = function(data, formattedData, rowIndex, colIndex) {
		if (data == "PC Game") {
			//gridView1.setCellColor(rowIndex, "textarea", "red");
			//gridView1.setCellBackgroundColor(rowIndex, "text", "yellow");
		}
		//return formattedData;

        return "12345";
	}
    scwin.customModelFormatter = function(value, formattedValue) {
		console.log("customModelFormatter:", arguments);
        return value.toUpperCase();
    }

    scwin.customModelUnformatter = function(value, formattedValue) {
		console.log("customModelUnformatter:", arguments);
        return value.toLowerCase();
    }
    scwin.displayFormatter = function(data){
	    //return data.substring(0,3) + "-" + data.substring(3,5);
        return "12345";
	}
    scwin.displayFormatFunc = function(type) {
        switch(type) {
            case "yearMonthDate" :
                return "dd.MM.yyyy";
            break;
            case "yearMonth" :
                return "MM.yyyy";
            break;
        }
    }
    scwin.onviewchange = function(info) {
        console.log(info.oldValue);
        console.log(info.newValue);
        console.log(info.rowIndex);
        console.log(info.colIndex);
        console.log(info.colId);
    }


	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate = function() {
		scwin.simulateWrapper('#gridView1_cell_0_0', 'drag-n-drop', {
			dx: 0,
			dy: 30
		});
	}

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_1_0').innerText == '10002';
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_1_1').innerText == 'Busan';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		//WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_0').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
